CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email TEXT UNIQUE NOT NULL, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'player', suspended BOOLEAN NOT NULL DEFAULT false, mfa_enabled BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS refresh_tokens(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, rotated_from UUID, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS profiles(user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, level INT NOT NULL DEFAULT 1, xp INT NOT NULL DEFAULT 0, avatar TEXT NOT NULL DEFAULT 'h0rii-default', status_message TEXT NOT NULL DEFAULT 'Ready', updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cosmetics(id TEXT PRIMARY KEY, category TEXT NOT NULL, name TEXT NOT NULL, rarity TEXT NOT NULL DEFAULT 'common', asset_url TEXT, enabled BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS inventory(user_id UUID REFERENCES users(id) ON DELETE CASCADE, cosmetic_id TEXT REFERENCES cosmetics(id), favorite BOOLEAN NOT NULL DEFAULT false, PRIMARY KEY(user_id, cosmetic_id));
CREATE TABLE IF NOT EXISTS equipped(user_id UUID REFERENCES users(id) ON DELETE CASCADE, category TEXT NOT NULL, cosmetic_id TEXT REFERENCES cosmetics(id), PRIMARY KEY(user_id, category));
CREATE TABLE IF NOT EXISTS friends(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), requester_id UUID REFERENCES users(id) ON DELETE CASCADE, addressee_id UUID REFERENCES users(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'pending', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(requester_id, addressee_id));
CREATE TABLE IF NOT EXISTS parties(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), leader_id UUID REFERENCES users(id) ON DELETE SET NULL, privacy TEXT NOT NULL DEFAULT 'friends', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS party_members(party_id UUID REFERENCES parties(id) ON DELETE CASCADE, user_id UUID REFERENCES users(id) ON DELETE CASCADE, ready BOOLEAN NOT NULL DEFAULT false, joined_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(party_id,user_id));
CREATE TABLE IF NOT EXISTS matchmaking_tickets(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), party_id UUID REFERENCES parties(id) ON DELETE SET NULL, user_id UUID REFERENCES users(id) ON DELETE SET NULL, region TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id UUID REFERENCES matchmaking_tickets(id) ON DELETE SET NULL, region TEXT NOT NULL, adapter TEXT NOT NULL DEFAULT 'mock', connection_json JSONB NOT NULL, status TEXT NOT NULL DEFAULT 'allocated', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), ended_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS audit_logs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), actor_id UUID, action TEXT NOT NULL, target_type TEXT, target_id TEXT, metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
